export const EDUCATION_V2_P1_800_TARGET_PER_ROUTE = 200;

export const EDUCATION_V2_P1_800_CATEGORY_TARGETS = {
  FAST_READING: 60,
  READING_COMPREHENSION: 80,
  COMMON_STRATEGIES: 20,
  INTEGRATED_PRACTICE: 25,
  MULTI_SKILL_ASSESSMENT: 15,
} as const;

export type EducationV2P1ExpansionCategory = keyof typeof EDUCATION_V2_P1_800_CATEGORY_TARGETS;

export type EducationV2P1ExpansionDifficulty = "FOUNDATION" | "INTERMEDIATE" | "ADVANCED";

export type EducationV2P1ExpansionSourceEvidence = {
  title: string;
  url: string;
  checkedOn: string;
  verifiedFacts: readonly string[];
  contentRelation: string;
};

type DraftQuestion = {
  key: string;
  prompt: string;
  correct: string;
  distractors: [string, string, string];
  explanation: string;
  hint: string;
};

type DraftStation = {
  key: string;
  title: string;
  category: EducationV2P1ExpansionCategory;
  skillCodes: string[];
  outcome: string;
  textTitle: string;
  text: string;
  sourceReference: string;
  sourceEvidence?: EducationV2P1ExpansionSourceEvidence;
  provenanceStatus: "SOURCE_VERIFIED" | "REVIEW_REQUIRED";
  questions: [DraftQuestion, DraftQuestion, DraftQuestion];
};

type RouteDraft = {
  routeFamily: "A" | "B" | "C" | "D";
  priorSequence: number;
  priorPathCode: string;
  nextSequence: number;
  positionOffset: number;
  stations: [DraftStation, DraftStation, DraftStation, DraftStation, DraftStation];
};

const q = (
  key: string,
  prompt: string,
  correct: string,
  distractors: [string, string, string],
  explanation: string,
  hint: string,
): DraftQuestion => ({ key, prompt, correct, distractors, explanation, hint });

const sourceEvidence = (
  title: string,
  url: string,
  verifiedFacts: readonly string[],
  contentRelation: string,
  checkedOn = "2026-10-17",
): EducationV2P1ExpansionSourceEvidence => ({
  title,
  url,
  checkedOn,
  verifiedFacts,
  contentRelation,
});

