const station = (
  key: string,
  title: string,
  category: EducationV2P1ExpansionCategory,
  skillCodes: string[],
  outcome: string,
  textTitle: string,
  text: string,
  sourceReference: string,
  questions: [DraftQuestion, DraftQuestion, DraftQuestion],
  sourceEvidence?: EducationV2P1ExpansionSourceEvidence,
): DraftStation => ({
  key,
  title,
  category,
  skillCodes,
  outcome,
  textTitle,
  text,
  sourceReference,
  ...(sourceEvidence ? { sourceEvidence } : {}),
  provenanceStatus: sourceEvidence ? "SOURCE_VERIFIED" : "REVIEW_REQUIRED",
  questions,
});

const sourcedStation = (
  key: string,
  title: string,
  category: EducationV2P1ExpansionCategory,
  skillCodes: string[],
  outcome: string,
  textTitle: string,
  text: string,
  sourceTitle: string,
  sourceUrl: string,
  verifiedFacts: readonly string[],
  contentRelation: string,
  questions: [DraftQuestion, DraftQuestion, DraftQuestion],
  checkedOn = "2026-10-17",
): DraftStation => {
  const evidence = sourceEvidence(
    sourceTitle,
    sourceUrl,
    verifiedFacts,
    contentRelation,
    checkedOn,
  );
  return station(
    key,
    title,
    category,
    skillCodes,
    outcome,
    textTitle,
    text,
    contentRelation,
    questions,
    evidence,
  );
};

