const unlinkedDraftCycles = routeDrafts.map(buildDraftCycle);

export const EDUCATION_V2_P1_800_DRAFT_CYCLES = unlinkedDraftCycles.map((cycle) => ({
  ...cycle,
  nextPathCode:
    unlinkedDraftCycles.find(
      (candidate) =>
        candidate.routeFamily === cycle.routeFamily && candidate.sequence === cycle.sequence + 1,
    )?.pathCode ?? null,
}));

